  SELECT 1 FROM `sys_integration_api_endpoint` e
  WHERE e.`system_code` = s.`system_code` AND e.`resource_group` = s.`resource_group`
    AND e.`http_method` = s.`http_method` AND e.`api_path` = s.`api_path`
);

